#include <iostream>
#include <string>

enum class Light { Red, Green, Yellow };

Light next(Light light) {
    switch (light) {
    case Light::Red:
        return Light::Green;
    case Light::Green:
        return Light::Yellow;
    case Light::Yellow:
        return Light::Red;
    }
    return Light::Red;
}

std::string name(Light light) {
    switch (light) {
    case Light::Red:
        return "красный";
    case Light::Green:
        return "зелёный";
    case Light::Yellow:
        return "жёлтый";
    }
    return "?";
}

int main() {
    std::string start;
    int n;
    while (std::cin >> start >> n) {
        Light light = start == "red" ? Light::Red : start == "green" ? Light::Green : Light::Yellow;
        for (int i = 0; i <= n; i++) {
            std::cout << name(light) << (i < n ? ' ' : '\n');
            light = next(light);
        }
    }
    return 0;
}

