#include <iostream>
#include <string>

enum class Direction { North, East, South, West };

Direction turn(Direction d, int quarter) {
    return static_cast<Direction>((static_cast<int>(d) + quarter) % 4);
}

std::string name(Direction d) {
    switch (d) {
    case Direction::North:
        return "север";
    case Direction::East:
        return "восток";
    case Direction::South:
        return "юг";
    case Direction::West:
        return "запад";
    }
    return "?";
}

int main() {
    long long x = 0, y = 0;
    Direction d = Direction::North;
    std::string command;
    while (std::cin >> command) {
        if (command == "L") {
            d = turn(d, 3);
        } else if (command == "R") {
            d = turn(d, 1);
        } else if (command == "F") {
            long long k;
            std::cin >> k;
            switch (d) {
            case Direction::North:
                y += k;
                break;
            case Direction::East:
                x += k;
                break;
            case Direction::South:
                y -= k;
                break;
            case Direction::West:
                x -= k;
                break;
            }
        }
    }
    std::cout << x << ' ' << y << ' ' << name(d) << '\n';
    return 0;
}

