#include <iostream>

enum class Op { Add, Sub, Mul };

int apply(Op op, int a, int b) {
    switch (op) {
    case Op::Add:
        return a + b;
    case Op::Sub:
        return a - b;
    case Op::Mul:
        return a * b;
    }
    return 0;
}

int main() {
    std::cout << apply(Op::Mul, apply(Op::Add, 2, 3), apply(Op::Sub, 10, 6)) << '\n';
    return 0;
}

